namespace {

const schema::ClassSchema& replicator() { return schema_named("ANodeLayoutReplicator"); }

/// The raw bits of a capture case, on a heap buffer of exactly the bytes they need.
template <class F>
auto with_case(const capture_node_layout::Case& c, F f) {
    return with_exact(bits_of_hex(c.hex, c.bits), f);
}

bool same_bits(const BunchWriter& w, const std::vector<uint8_t>& want, size_t bits) {
    if (w.bit_pos() != bits) return false;
    for (size_t i = 0; i < bits; ++i) {
        if (((w.bytes()[i >> 3] >> (i & 7)) & 1) != ((want[i >> 3] >> (i & 7)) & 1)) return false;
    }
    return true;
}

void test_schema() {
    std::printf("the schema\n");
    const schema::ClassSchema& s = replicator();
    CHECK(node_layout_schema_ok(s), "ANodeLayoutReplicator: LayoutAssetSetGuids is a fast array with a header and the seven-member item");
    const schema::NetField* f = s.field("LayoutAssetSetGuids");
    CHECK(f && (f->flags & schema::kRepFastArray) && (f->flags & schema::kRepCustomDelta), "its field is a custom-delta fast array");
    CHECK(s.field("NodeGuid") && s.commands.size() == 25 && s.fields.size() == 15, "25 RepLayout commands and 15 net fields (the base actor's and the two of the class)");
    CHECK(!node_layout_schema_ok(schema_named("AAoCGameStateBase")), "another class is not the replicator");
}
// ~ Cyb :: C O A ~

void test_retail() {
    std::printf("the 18 retail payloads\n");
    size_t n = 0;
    for (const capture_node_layout::Case& c : capture_node_layout::kCases) {
        ++n;
        const std::string what = std::string(c.source) + " (node " + std::to_string(c.node) + ", level " + std::to_string(c.level) + ", season " + std::to_string(c.season) + ")";
        const auto payload = with_case(c, [&](const uint8_t* d, size_t, size_t bits) { return read_node_layout_payload(replicator(), d, bits); });
        CHECK(payload.has_value(), (what + ": reads to its last bit").c_str());
        if (!payload) continue;
        const size_t items = payload->items.size();
        const bool tag = payload->header.tags == std::vector<std::string>{"War.Siege.States.SiegeInactive"};
        CHECK(payload->header.level == c.level && payload->header.culture == c.culture && payload->header.season == c.season && tag && payload->base_key == 0 && payload->deleted.empty(),
              (what + ": the header (level, culture 0, season, the SiegeInactive tag), base key 0 and no deletes").c_str());
        CHECK(c.bits == 353 + 128 + 800 * items, (what + ": " + std::to_string(c.bits) + " bits = 353 + 128 + 800 x " + std::to_string(items) + " items").c_str());
        // the typed payload written again
        BunchWriter w;
        const size_t bits = write_node_layout_snapshot(replicator(), *payload, w);
        const std::vector<uint8_t> want = bytes_of_hex(c.hex);
        CHECK(bits == c.bits && same_bits(w, want, c.bits), (what + ": written again from the typed payload it is the exact bits of the capture").c_str());
        // every item: the quaternion's W is derived, so a value must keep X, Y, Z (nothing is normalised on the way)
        bool all_prop_or_plot = true;
        for (const auto& e : payload->items) all_prop_or_plot = all_prop_or_plot && e.item.asset_set != 0 && e.item.owner_guid != 0;
        CHECK(all_prop_or_plot, (what + ": every item names an owner and an asset set").c_str());
    }
    CHECK(n == 18, "18 cases");
}

void test_header() {
    std::printf("the header\n");
    NodeLayoutHeader h;
    h.level = 4;
    h.season = 2;
    h.plot_version = 7;
    // no tag: the empty bit and nothing else
    BunchWriter w0;
    CHECK(write_node_layout_header(h, w0) && w0.bit_pos() == 24 + 1 + 8, "no tag: 24 + 1 + 8 bits");
    size_t pos = 0;
    const auto back0 = with_exact(Bits(w0), [&](const uint8_t* d, size_t, size_t n) { return read_node_layout_header(d, n, pos); });
    CHECK(back0 && *back0 == h && pos == w0.bit_pos(), "it reads back");
    // two tags
    h.tags = {"War.Siege.States.SiegeInactive", "A.B"};
    BunchWriter w2;
    CHECK(write_node_layout_header(h, w2), "two tags write");
    const size_t expected = 24 + 1 + 6 + (1 + 32 + 31 * 8 + 32) + (1 + 32 + 4 * 8 + 32) + 8;
    CHECK(w2.bit_pos() == expected, "their size is the container's: the count, then per tag a bit, the length, the bytes with the NUL and the number");
    pos = 0;
    const auto back2 = with_exact(Bits(w2), [&](const uint8_t* d, size_t, size_t n) { return read_node_layout_header(d, n, pos); });
    CHECK(back2 && *back2 == h && pos == w2.bit_pos(), "they read back");
    const auto size = with_exact(Bits(w2), [&](const uint8_t* d, size_t, size_t n) { return node_layout_header_bits(d, n, 0); });
    CHECK(size && *size == w2.bit_pos(), "node_layout_header_bits is the header's size");
    // refusals
    NodeLayoutHeader bad = h;
    bad.tags = {""};
    BunchWriter wb;
    CHECK(!write_node_layout_header(bad, wb) && wb.bit_pos() == 0, "an empty tag is refused, nothing written");
    bad.tags.assign(64, "X");
    CHECK(!write_node_layout_header(bad, wb), "64 tags do not fit the 6-bit count");
    bad.tags = {"caf\xc3\xa9"};
    CHECK(!write_node_layout_header(bad, wb), "a non-ASCII tag is refused");
    bad.tags = {std::string(256, 'a')};
    CHECK(!write_node_layout_header(bad, wb), "a tag of 256 characters is refused");
    // a truncated header does not read, at any cut
    bool every_cut_refused = true;
    for (size_t cut = 0; cut < w2.bit_pos(); ++cut) {
        size_t p = 0;
        const auto r = with_exact(Bits(w2).slice(0, cut), [&](const uint8_t* d, size_t, size_t n) { return read_node_layout_header(d, n, p); });
        every_cut_refused = every_cut_refused && !r;
    }
    CHECK(every_cut_refused, "a header cut short at any bit does not read");
    // a hardcoded FName (not seen on the wire) is refused
    Bits hard = Bits(w2);
    hard.set(24 + 1 + 6, 1, 1);
    size_t p = 0;
    CHECK(!with_exact(hard, [&](const uint8_t* d, size_t, size_t n) { return read_node_layout_header(d, n, p); }), "a hardcoded FName is refused");
}
// (C O A + Cyb)

NodeLayoutItem item(int64_t owner, int32_t secondary, int32_t index, int64_t set, double tx) {
    NodeLayoutItem it;
    it.owner_guid = owner;
    it.owner_secondary = secondary;
    it.owner_index = index;
    it.asset_set = set;
    it.rotation = Quat{0.0, 0.0, 0.25};
    it.translation = Vec3d{tx, -tx, 12.5};
    it.scale = Vec3d{1, 1, 1};
    return it;
}

/// A client's copy: the field payloads applied in order to fresh arrays.
struct Client {
    FastArrays arrays;
    bool apply(const BunchWriter& w) {
        size_t pos = 0;
        const Bits all(w);
        const auto fields = with_exact(all, [&](const uint8_t* d, size_t, size_t n) { return read_fast_array_fields(replicator(), d, n, pos, {}); });
        if (!fields || pos != w.bit_pos()) return false;
        for (const FastArrayField& f : *fields) {
            FastArrayState* st = arrays.get(replicator(), f.field);
            if (!st || !apply_fast_array_delta(*st, f.delta)) return false;
        }
        return true;
    }
};

void test_server() {
    std::printf("the server's side\n");
    // the first sync of a retail payload's header and items: IDs 1..N, the key N, and the field writes the payload's bits
    const capture_node_layout::Case& c = capture_node_layout::kCases[0];
    const auto retail = with_case(c, [&](const uint8_t* d, size_t, size_t bits) { return read_node_layout_payload(replicator(), d, bits); });
    CHECK(retail.has_value(), "the first retail payload reads");
    if (!retail) return;
    std::vector<NodeLayoutItem> items;
    for (const auto& e : retail->items) items.push_back(e.item);
    FastArrays arrays;
    NodeLayoutSync r;
    CHECK(sync_node_layout(replicator(), arrays, retail->header, items, &r) && r.changed && r.added == items.size() && r.removed == 0 && r.header_changed, "the first sync adds every item");
    const auto state = read_node_layout_state(replicator(), arrays);
    bool ids = state && state->items.size() == items.size();
    for (size_t i = 0; ids && i < items.size(); ++i) ids = state->items[i].id == static_cast<int32_t>(i + 1) && state->items[i].item == items[i];
    CHECK(ids && state->array_key == static_cast<int32_t>(items.size()), "IDs 1..N in order and ArrayReplicationKey N: what a fresh server sends");
    FastArrayShadows shadows;
    BunchWriter field;
    bool failed = false;
    const size_t fbits = write_fast_array_fields(replicator(), arrays, shadows, field, {}, &failed);
    CHECK(!failed && fbits > c.bits, "the field loop writes the payload behind a field header");
    Client client;
    CHECK(client.apply(field), "a client reads the field loop and applies it (the header travels in the delta)");
    const auto theirs = read_node_layout_state(replicator(), client.arrays);
    CHECK(theirs && theirs->header == retail->header && theirs->items.size() == items.size() && theirs->array_key == state->array_key, "its copy has the header, the items and the key");
    bool same_items = theirs.has_value();
    for (size_t i = 0; same_items && i < items.size(); ++i) same_items = theirs->items[i].item == items[i] && theirs->items[i].id == state->items[i].id;
    CHECK(same_items, "and every item as the server holds it");

    // nothing changed: nothing sent
    NodeLayoutSync again;
    CHECK(sync_node_layout(replicator(), arrays, retail->header, items, &again) && !again.changed, "the same header and items again change nothing");
    BunchWriter none;
    CHECK(write_fast_array_fields(replicator(), arrays, shadows, none, {}) == 0, "a connection that has them is sent nothing");

    // a level change: a new full list; the header's level, season and PlotChangeVersion new
    NodeLayoutHeader next = retail->header;
    next.level = 3;
    next.plot_version = static_cast<uint8_t>(next.plot_version + 1);
    std::vector<NodeLayoutItem> fewer(items.begin(), items.begin() + 10);
    fewer.push_back(item(77, 2, 0, 999, 100));
    NodeLayoutSync lv;
    CHECK(sync_node_layout(replicator(), arrays, next, fewer, &lv) && lv.changed && lv.removed == items.size() && lv.added == fewer.size() && lv.header_changed, "a level change removes every old item and adds the new list");
    BunchWriter delta;
    const size_t dbits = write_fast_array_fields(replicator(), arrays, shadows, delta, {}, &failed);
    CHECK(!failed && dbits > 0, "the connection is sent one delta");
    size_t pos = 0;
    const auto fields = with_exact(Bits(delta), [&](const uint8_t* d, size_t, size_t n) { return read_fast_array_fields(replicator(), d, n, pos, {}); });
    CHECK(fields && fields->size() == 1 && (*fields)[0].delta.deleted.size() == items.size() && (*fields)[0].delta.changed.size() == fewer.size() &&
              (*fields)[0].delta.base_key == static_cast<int32_t>(items.size()),
          "it deletes every old ID and carries the new items, against the key the connection had");
    CHECK(client.apply(delta), "the client applies it");
    const auto after = read_node_layout_state(replicator(), client.arrays);
    const auto server_after = read_node_layout_state(replicator(), arrays);
    bool equal = after && server_after && after->header == next && after->items.size() == fewer.size();
    for (size_t i = 0; equal && i < fewer.size(); ++i) equal = after->items[i].item == fewer[i] && after->items[i].id == server_after->items[i].id;
    CHECK(equal && after->header.level == 3 && after->header.plot_version == retail->header.plot_version + 1, "the client ends up with the new level, the bumped PlotChangeVersion and exactly the new items");

    // a header-only change (PlotChangeVersion): the key moves, no item is carried
    NodeLayoutHeader bump = next;
    bump.plot_version = static_cast<uint8_t>(bump.plot_version + 1);
    NodeLayoutSync hs;
    CHECK(sync_node_layout(replicator(), arrays, bump, fewer, &hs) && hs.changed && hs.added == fewer.size() && hs.removed == fewer.size(), "a changed header with the same items is a full list again");
    BunchWriter hd;
    CHECK(write_fast_array_fields(replicator(), arrays, shadows, hd, {}) > 0 && client.apply(hd), "and it reaches the client");
    const auto hafter = read_node_layout_state(replicator(), client.arrays);
    CHECK(hafter && hafter->header == bump, "who has the new PlotChangeVersion");

    // refusals: a wrong schema, a header that does not write
    FastArrays other;
    CHECK(!sync_node_layout(schema_named("AAoCGameStateBase"), other, bump, fewer), "a schema that is not the replicator's is refused");
    NodeLayoutHeader worse = bump;
    worse.tags = {""};
    FastArrays third;
    CHECK(!sync_node_layout(replicator(), third, worse, fewer) && !read_node_layout_state(replicator(), third), "a header that does not write is refused and leaves the array empty");

    // a layout with a header and none set cannot be written
    const auto layout = fast_array_layout(replicator(), "LayoutAssetSetGuids");
    FastArrayState bare(*layout);
    bare.add(node_layout_item_values(fewer[0]));
    FastArrayShadow sh;
    BunchWriter wb;
    bool bad = false;
    CHECK(write_fast_array_delta(bare, sh, wb, {}, &bad) == 0 && bad && wb.bit_pos() == 0, "a fast array of this layout with no header set is refused, nothing written");
// C.O.A.C_Y_B

    // every truncation of a payload fails to read (no crash, no short read taken for a whole payload)
    bool all_cuts = true;
    const std::vector<uint8_t> want = bytes_of_hex(capture_node_layout::kCases[8].hex);   // a 16-item payload
    const size_t total = capture_node_layout::kCases[8].bits;
    for (size_t cut = 0; cut < total; cut += 97) {
        const Bits part = bits_of_hex(capture_node_layout::kCases[8].hex, total).slice(0, cut);
        const auto p = with_exact(part, [&](const uint8_t* d, size_t, size_t n) { return read_node_layout_payload(replicator(), d, n); });
        all_cuts = all_cuts && !p;
    }
    CHECK(all_cuts, "a payload cut short does not read");
}

}  // namespace

int main() {
    test_schema();
    test_retail();
    test_header();
    test_server();
    std::printf("\n%d passed, %d failed\n", g_pass, g_fail);
    return g_fail == 0 ? 0 : 1;
}
